def accrue_past_visits(apps, schema_editor):
    """Запуск бонусной программы: 5% за уже выполненные визиты, один раз."""
    Booking = apps.get_model("bookings", "Booking")
    BonusOperation = apps.get_model("bookings", "BonusOperation")
    for b in Booking.objects.filter(status="completed", price__gt=0).select_related("service"):
        points = int(b.price * 5 / 100)
        if points:
            BonusOperation.objects.create(client_id=b.client_id, booking=b, amount=points,
                                          comment=f"За визит: {b.service.name}")


